1	import type { FC } from "react";
2	import { AttachmentListEditor, LocationDisplayEditor, RelationListEditor } from "@/components/MemoMetadata";
3	import { useEditorContext, useEditorSelector } from "../state";
4	import type { EditorMetadataProps } from "../types";
5	
6	export const EditorMetadata: FC<EditorMetadataProps> = ({ memoName }) => {
7	  const { actions, dispatch } = useEditorContext();
8	  const attachments = useEditorSelector((s) => s.metadata.attachments);
9	  const localFiles = useEditorSelector((s) => s.localFiles);
10	  const relations = useEditorSelector((s) => s.metadata.relations);
11	  const location = useEditorSelector((s) => s.metadata.location);
12	
13	  return (
14	    <div className="w-full flex flex-col gap-2">
15	      <AttachmentListEditor
16	        attachments={attachments}
17	        localFiles={localFiles}
18	        onAttachmentsChange={(next) => dispatch(actions.setMetadata({ attachments: next }))}
19	        onLocalFilesChange={(next) => dispatch(actions.setLocalFiles(next))}
20	        onRemoveLocalFile={(previewUrl) => dispatch(actions.removeLocalFile(previewUrl))}
21	      />
22	
23	      <RelationListEditor
24	        relations={relations}
25	        onRelationsChange={(next) => dispatch(actions.setMetadata({ relations: next }))}
26	        memoName={memoName}
27	      />
28	
29	      {location && <LocationDisplayEditor location={location} onRemove={() => dispatch(actions.setMetadata({ location: undefined }))} />}
30	    </div>
31	  );
32	};
